cd /app/work && python - <<'EOF'
import json
for kind in ["infeas_mlu","infeas_fail"]:
    for line in open(f"req_max_{kind}.jsonl"):
        r=json.loads(line)
        edges=r["edges"]; bad=[]
        for k,c in enumerate(r["commodities"]):
            for p in c["paths"]:
                cur=c["source"]; ok=True
                for e in p:
                    if edges[e]["tail"]!=cur: ok=False;break
                    cur=edges[e]["head"]
                if not ok or cur!=c["target"]:
                    bad.append((k,p[:6]))
        print(kind, "structurally bad paths:", len(bad), bad[:3], "epoch", r["epoch"])
EOF
